function O.learn()
local YQb,ZQb={},{}
local _Qb,aRb=0,0
for bRb,cRb in ipairs(O.mine)do
local dRb=cRb._stats
local eRb=dRb.id.Value
local fRb=dRb:FindFirstChild(xic[2678])and dRb.total_damage.Value or 0
if not L.isFarm(eRb)then
YQb[eRb]=(YQb[eRb]or 0)+fRb
ZQb[eRb]=(ZQb[eRb]or 0)+O.liveDps(cRb,eRb)/math.max(0.5,L.nudge(eRb))
local gRb=L.passive(eRb).mark
if gRb then
ZQb[eRb]=ZQb[eRb]+gRb.dot*dRb.damage.Value
end
_Qb=_Qb+fRb
end
end
for hRb,iRb in pairs(ZQb)do
aRb=aRb+iRb
end
if _Qb<=0 or aRb<=0 then
return
end
O.lastEff={}
for jRb,kRb in pairs(YQb)do
local lRb,mRb=kRb/_Qb,ZQb[jRb]/aRb
if mRb>0.02 then
local nRb=H.learn[jRb]or{eff=1,n=0}
local oRb=math.max(0.02,0.25*math.sqrt(30/(30+nRb.n)))
local pRb=K.clamp(lRb/mRb,0.3,3)
O.lastEff[jRb]=math.floor(pRb*1000+0.5)/1000
nRb.eff=nRb.eff+(pRb-nRb.eff)*oRb
nRb.n=nRb.n+1
H.learn[jRb]=nRb
end
end
end
